/**
 * PropsLayer.tsx — W-009 world dressing from the user-supplied prop packs.
 *
 * Architecture (draw-call budget: e2e asserts < 450 on street scenes):
 *   - 88 colorized meshopt GLBs (PROP_KITS, one shared untextured
 *     vertexColors material — colors are baked per-face into the geometry)
 *   - PROP_PLACEMENTS (403 items, generated by scripts/emit-placements.mjs
 *     with roads/colliders/plots/sea all blocked off) are grouped into
 *     spatial cells (48 m grid, keyed by district for debugging) —
 *     DISTRICT-wide merges were tried first, but a district mesh's
 *     bounding sphere spans its whole name-area, defeats frustum culling
 *     and kept ~10 full-district geometries in every street frame. Cells
 *     cull to the few in view (design intent: ~3-8 draw calls per street
 *     view) while aerial overviews pay one draw per occupied cell.
 *   - each cell's instances are TRANSFORMED + MERGED into ONE
 *     BufferGeometry → one <mesh> per cell
 *
 * Dressing-only: no colliders (colliders.json is capture-provenance, ?capture=1
 * still unwired — same contract as W-006 plot dressing). userData.noCollide
 * marks the meshes for the collider export tooling. No shadow casting —
 * the merged cells are pure street clutter; the shadow pass would double
 * the raster load for no readable gain (props sit inside building shadows).
 */
import { Suspense, useMemo } from 'react'
import * as THREE from 'three'
import { useGLTF } from '@react-three/drei'
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js'
import { PROP_KITS, PROP_URLS } from './propsKit'
import { PROP_PLACEMENTS, type PropPlacement } from './propPlacements'
import { publicUrl } from '../gltfSupport'

/** deterministic variant pick per placement (hero kits ship 2 geometries) */
function variantIndex(kit: string, x: number, z: number, count: number): number {
  if (count <= 1) return 0
  const h = Math.sin(x * 12.9898 + z * 78.233) * 43758.5453
  return Math.abs(h - Math.floor(h)) < 0.5 ? 0 : 1
}

/** de-interleave GLTF attributes — meshopt-decoded geometries arrive as
 *  InterleavedBufferAttribute, and BufferGeometry.applyMatrix4 does NOT
 *  update interleaved data in three 0.186 (props would silently pile up at
 *  the origin). Copy every attribute into a plain BufferAttribute. */
function deinterleave(g: THREE.BufferGeometry): THREE.BufferGeometry {
  for (const name of Object.keys(g.attributes)) {
    const a = g.getAttribute(name)
    if ('isInterleavedBufferAttribute' in a && a.isInterleavedBufferAttribute) {
      // read via getX/getY/... — they apply normalization/quantization decode,
      // unlike raw buffer access (KHR_mesh_quantization stores Int16)
      const itemSize = a.itemSize
      const arr = new Float32Array(a.count * itemSize)
      for (let i = 0; i < a.count; i++) {
        arr[i * itemSize] = a.getX(i)
        if (itemSize > 1) arr[i * itemSize + 1] = a.getY(i)
        if (itemSize > 2) arr[i * itemSize + 2] = a.getZ(i)
        if (itemSize > 3) arr[i * itemSize + 3] = a.getW(i)
      }
      g.setAttribute(name, new THREE.BufferAttribute(arr, itemSize))
    }
  }
  return g
}

/** strip a loaded GLTF scene down to plain non-indexed geometry (positions +
 *  normals + the baked COLOR_0) */
function kitGeometries(scene: THREE.Object3D): THREE.BufferGeometry[] {
  const out: THREE.BufferGeometry[] = []
  scene.updateMatrixWorld(true)
  scene.traverse((o) => {
    const mesh = o as THREE.Mesh
    if (!mesh.isMesh) return
    const g = deinterleave(mesh.geometry.clone())
    g.applyMatrix4(mesh.matrixWorld)
    const flat = g.index ? g.toNonIndexed() : g
    for (const name of Object.keys(flat.attributes)) {
      if (name !== 'position' && name !== 'normal' && name !== 'color') flat.deleteAttribute(name)
    }
    if (!flat.getAttribute('color')) return // uncolored kit — never ship
    out.push(flat)
  })
  return out
}

function PropsWorld() {
  const gtfs = useGLTF(PROP_URLS, false, true)

  const districtGeometries = useMemo(() => {
    // url → geometry (useGLTF with an array returns results in input order)
    const byUrl = new Map<string, THREE.BufferGeometry[]>()
    PROP_URLS.forEach((url, i) => {
      const gltf = Array.isArray(gtfs) ? gtfs[i] : gtfs
      const scene = (gltf as { scene: THREE.Object3D }).scene
      const geos = kitGeometries(scene)
      if (geos.length > 0) byUrl.set(url, geos)
    })

    const kitGeo = new Map<string, THREE.BufferGeometry[]>()
    for (const [kit, files] of Object.entries(PROP_KITS)) {
      const geos = files.flatMap((f) => byUrl.get(publicUrl(f)) ?? [])
      if (geos.length > 0) kitGeo.set(kit, geos)
    }

    // group placements into spatial cells (48 m grid over the plate) —
    // district-sized merges defeat frustum culling (see header note)
    const CELL = 48;
    const buckets = new Map<string, PropPlacement[]>();
    for (const p of PROP_PLACEMENTS) {
      if (!kitGeo.has(p.k)) {
        if (import.meta.env.DEV) console.warn(`[props] placement references unknown kit '${p.k}' — skipped`)
        continue
      }
      const key = `${p.d}#${Math.floor((p.x + 360) / CELL)}_${Math.floor((p.z + 140) / CELL)}`
      const list = buckets.get(key) ?? []
      list.push(p)
      buckets.set(key, list)
    }

    const out: { district: string; geometry: THREE.BufferGeometry }[] = []
    const m = new THREE.Matrix4()
    const q = new THREE.Quaternion()
    const e = new THREE.Euler()
    const v = new THREE.Vector3()
    const sv = new THREE.Vector3()
    for (const [district, items] of buckets) {
      const parts: THREE.BufferGeometry[] = []
      for (const it of items) {
        const variants = kitGeo.get(it.k)!
        const geo = variants[variantIndex(it.k, it.x, it.z, variants.length)]
        const g = geo.clone()
        e.set(0, (it.r * Math.PI) / 180, 0)
        q.setFromEuler(e)
        v.set(it.x, 0, it.z)
        sv.set(it.s, it.s, it.s)
        m.compose(v, q, sv)
        g.applyMatrix4(m)
        parts.push(g)
      }
      if (parts.length === 0) continue
      const merged = mergeGeometries(parts, false)
      for (const p of parts) p.dispose()
      if (merged) {
        merged.computeBoundingSphere()
        merged.computeBoundingBox()
        out.push({ district, geometry: merged })
      }
    }
    return out
  }, [gtfs])

  const material = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        vertexColors: true,
        roughness: 0.85,
        metalness: 0,
      }),
    []
  )

  return (
    <group name="props-layer">
      {districtGeometries.map(({ district, geometry }) => (
        <mesh
          key={district}
          name={`props-${district}`}
          geometry={geometry}
          material={material}
          userData={{ noCollide: true }}
        />
      ))}
    </group>
  )
}

export function PropsLayer() {
  return (
    <Suspense fallback={null}>
      <PropsWorld />
    </Suspense>
  )
}
